@push('css')
<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.3/css/all.min.css" />
<style>
    /* ============================================================
       User Wallet page — balance + transaction history + Buy Credits
       modal that embeds the PurchaseCredits Livewire component in
       modal mode (passes inModal=true). Class prefix .uw-* to avoid
       colliding with .pc-v2-* (mobile v2 inside purchase-credits),
       .cc-*, .pm-*, etc.
       ============================================================ */
    [x-cloak] { display: none !important; }
    body { background: #000 !important; }
    body > .ev-header-account { display: none !important; }

    .uw-page { background: #000; min-height: 100vh; color: #fff; padding-bottom: 60px; }

    .uw-back-wrap { background: #131616; padding: 14px 0; margin-bottom: 32px; }
    .uw-back-wrap .ev-container {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 12px;
    }
    .uw-back-link {
        color: #C1F11D;
        font-size: 14px;
        text-decoration: none;
        display: inline-flex;
        align-items: center;
        gap: 6px;
        font-weight: 500;
    }
    .uw-back-link:hover { color: #d9ff4a; }
    .uw-crumb-title {
        color: #fff;
        font-size: 14px;
        font-weight: 500;
        margin: 0;
    }
    .uw-crumb-spacer { width: 60px; }

    /* Shared container width — hero head and the two-column grid both
       sit inside this so they share the same horizontal gutters. */
    .uw-container {
        max-width: 1240px;
        margin: 0 auto;
        padding: 0 16px;
    }
    .uw-grid {
        display: grid;
        grid-template-columns: minmax(0, 1fr) 300px;
        gap: 24px;
        align-items: start;
    }
    @media (max-width: 900px) {
        .uw-grid { grid-template-columns: 1fr; }
    }

    /* ─── Hero head (icon + title + subtitle) ─── */
    .uw-hero-head {
        display: flex;
        align-items: center;
        gap: 14px;
        margin-bottom: 18px;
    }
    .uw-hero-icon {
        width: 60px;
        height: 60px;
        border-radius: 50%;
        /* Two layered gradients + transparent border = gradient border on
           a rounded shape (border-image doesn't honor border-radius). */
        background:
            linear-gradient(180deg, #0F2821 0%, #153421 40.38%, #1A3D21 72.12%, #216D27 100%) padding-box,
            linear-gradient(180deg, #1F4C41 0%, #275828 100%) border-box;
        border: 1px solid transparent;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        flex-shrink: 0;
    }
    .uw-hero-head h2 {
        color: #fff;
        font-size: 26px;
        font-weight: 500;
        margin: 0 0 0px;
        line-height: 1.2;
    }
    .uw-hero-head p {
        color: #A6B4B8;
        font-size: 16px;
        margin: 0;
     
    }

    /* ─── Available Credits card ─── */
    .uw-balance {
        position: relative;
        /* Image sits on top of the gradient (first entry = top layer),
           so the walletback.png texture overlays the base dark-green fade. */
        background:
            url('https://assets.evoory.com/assets/images/walletback.png') no-repeat right center / cover,
            linear-gradient(90deg, #101E1B 0%, #2B421B 100%);
        border: 0px solid #51BF95;
        border-radius: 10px;
        padding: 11px 24px 11px 12px;
        margin-bottom: 24px;
        display: flex;
        align-items: center;
        gap: 18px;
        overflow: hidden;
    }
    .uw-balance-icon {
        position: relative;
        width: 56px;
        height: 56px;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        flex-shrink: 0;
    }
    /* Backdrop shape behind the coins: a solid gradient circle (the
       "head") with a trapezoid "skirt" extending from its mid-height
       downward, widening as it goes. Both share the same gradient so
       they blend into a single continuous shape. */
    
    .uw-balance-icon svg { position: relative; z-index: 1; }
    .uw-balance-info { flex: 1 1 auto; min-width: 0; }
    .uw-balance-label {
        color: white;
        font-size: 14px;
        font-weight: 500;
        margin-bottom: 4px;
    }
    .uw-balance-amount {
        color: #fff;
        font-size: 32px;
        font-weight: 500;
        line-height: 1.1;
        letter-spacing: -0.01em;
    }
    .uw-balance-sub {
        color: #A6B4B8;

        font-size: 12px;
        margin-top: 2px;
    }
    .uw-buy-btn {
       padding: 8px 14px;
    border-radius: 999px;
    border: none;
    background: #C1F11D;
    color: #0a0a0a;
    font-weight: 500;
    font-size: 14px;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-family: inherit;
    white-space: nowrap;
    transition: filter 120ms, transform 120ms;
}
    .uw-buy-btn:hover { filter: brightness(1.08); transform: translateY(-1px); }

    /* ─── Transaction History card ─── */
    .uw-tx-card {
        background: #131616;
        border: 1px solid #242B2D;
        border-radius: 10px;
        padding: 22px 24px 24px;
    }
    .uw-tx-head { margin-bottom: 16px; }
    .uw-tx-head h3 {
        color: #fff;
        font-size: 18px;
        font-weight: 600;
        margin: 0 0 2px;
    }
    .uw-tx-head p {
        color: rgba(255,255,255,0.5);
        font-size: 13px;
        margin: 0;
    }

    .uw-tx-tabs {
        display: inline-flex;
        align-items: center;
        gap: 10px;
        margin-bottom: 16px;
    }
    /* Standalone "All" pill — looks the same whether active or not. */
    .uw-tx-tab {
        padding: 8px 22px;
        border-radius: 999px;
        border: none;
        background: #1a2124;
        color: rgba(255,255,255,0.7);
        font-size: 13px;
        font-weight: 500;
        cursor: pointer;
        font-family: inherit;
        transition: background 120ms, color 120ms;
    }
    .uw-tx-tab:hover { background: #232c30; color: #fff; }
    .uw-tx-tab.is-active { background: #C1F11D; color: #0a0a0a; }

    /* Grouped pill — Credits in / Credits out sit side-by-side inside a
       single dark pill container. Active child flips to the lime fill. */
    .uw-tx-tab-group {
        display: inline-flex;
        align-items: center;
        background: #1a2124;
        border-radius: 999px;
        padding: 4px;
    }
    .uw-tx-tab-sub {
        padding: 8px 18px;
        border-radius: 999px;
        border: none;
        background: transparent;
        color: rgba(255,255,255,0.7);
        font-size: 13px;
        font-weight: 500;
        cursor: pointer;
        font-family: inherit;
        transition: background 120ms, color 120ms;
    }
    .uw-tx-tab-sub:hover { color: #fff; }
    .uw-tx-tab-sub.is-active { background: #C1F11D; color: #0a0a0a; }

    /* Transactions table — scrolls horizontally on narrow viewports. */
    .uw-tx-scroll { overflow-x: auto; margin: 0 -24px -24px; }
    .uw-tx-table {
        width: 100%;
        border-collapse: collapse;
        min-width: 760px;
    }
    .uw-tx-table th {
        text-align: left;
        padding: 10px 14px;
        color: rgba(255,255,255,0.45);
        font-size: 12px;
        font-weight: 500;
        text-transform: uppercase;
        letter-spacing: 0.5px;
        border-bottom: 1px solid rgba(255,255,255,0.05);
    }
    .uw-tx-table th:first-child, .uw-tx-table td:first-child { padding-left: 24px; }
    .uw-tx-table th:last-child,  .uw-tx-table td:last-child  { padding-right: 24px; }
    .uw-tx-table td {
        padding: 14px;
        border-bottom: 1px solid rgba(255,255,255,0.04);
        vertical-align: middle;
        font-size: 13.5px;
    }
    .uw-tx-table tr:last-child td { border-bottom: none; }

    .uw-tx-type-cell { display: flex; align-items: center; gap: 10px; }
    .uw-tx-icon {
        width: 36px;
        height: 36px;
        border-radius: 50%;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        font-size: 14px;
        flex-shrink: 0;
    }
    .uw-tx-icon.is-in  { background: rgba(34,197,94,0.14); color: #22c55e; }
    .uw-tx-icon.is-out { background: rgba(239,68,68,0.14); color: #ef4444; }
    .uw-tx-icon svg { display: block; }
    .uw-tx-type-text { line-height: 1.3; }
    .uw-tx-type-title { color: #fff; font-weight: 500; }
    .uw-tx-type-sub   { color: rgba(255,255,255,0.45); font-size: 12px; }

    .uw-tx-amt.is-in  { color: #22c55e; font-weight: 600; }
    .uw-tx-amt.is-out { color: #ef4444; font-weight: 600; }

    .uw-tx-date { color: rgba(255,255,255,0.75); line-height: 1.35; }
    .uw-tx-date small { display: block; color: rgba(255,255,255,0.45); font-size: 12px; }

    .uw-tx-status {
        display: inline-flex;
        align-items: center;
        gap: 5px;
        padding: 4px 10px;
        border-radius: 999px;
        font-size: 12px;
        font-weight: 500;
    }
    .uw-tx-status.is-completed { background: rgba(34,197,94,0.12); color: #22c55e; }
    .uw-tx-status.is-pending   { background: rgba(234,179,8,0.14);  color: #eab308; }
    .uw-tx-status.is-failed    { background: rgba(239,68,68,0.14);  color: #ef4444; }
    .uw-tx-status.is-cancelled { background: rgba(148,163,184,0.14); color: #94a3b8; }

    .uw-tx-ref {
        color: rgba(255,255,255,0.55);
        font-family: ui-monospace, 'SFMono-Regular', Menlo, monospace;
        font-size: 12px;
    }

    .uw-tx-empty {
        padding: 40px 20px;
        text-align: center;
        color: rgba(255,255,255,0.45);
        font-size: 14px;
    }
    .uw-tx-empty i { font-size: 32px; margin-bottom: 10px; opacity: 0.4; display: block; }

    /* ─── Right sidebar ─── */
    .uw-side { display: flex; flex-direction: column; gap: 16px; }
    .uw-side-card {
        background: #131616;
        border: 1px solid #242B2D;
        border-radius: 10px;
        padding: 18px 20px;
    }
    /* Shield icon on the left, title + subtitle stacked on the right. */
    .uw-secure-row {
        display: flex;
        align-items: center;
        gap: 14px;
    }
    .uw-secure-row > svg { flex-shrink: 0; }
    .uw-secure-text { min-width: 0; }
    .uw-secure-text h4 { color: #fff; font-size: 12px; font-weight: 600; margin: 0 0 1px; }
    .uw-secure-text p  { color: rgba(255,255,255,0.5); font-size: 12.5px; line-height: 1.45; margin: 0; }

    .uw-accept-label { color: white; font-size: 11px; margin-bottom: 0px; }
    /* Single credit-cards SVG strip (hosted on the CDN). Full width of the
       sidebar, auto height so it keeps its aspect ratio. */
    .uw-accept-logos img {
        display: block;
        width: 100%;
        height: auto;
    }

    /* ─── Buy Credits modal ─── */
    .uw-modal {
        position: fixed;
        inset: 0;
        background: rgba(0,0,0,0.75);
        z-index: 9998;
        display: flex;
        align-items: flex-start;
        justify-content: center;
        padding: 40px 16px;
        overflow-y: auto;
    }
    .uw-modal-dialog {
        background: #0d1113;
        border: 1px solid #2a3236;
        border-radius: 12px;
        max-width: 720px;
        width: 100%;
        position: relative;
        padding: 24px 20px 20px;
    }
    .uw-modal-head {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 12px;
        margin-bottom: 18px;
        padding: 0 4px;
    }
    .uw-modal-title {
        color: #fff;
        font-size: 18px;
        font-weight: 600;
        margin: 0;
    }
    .uw-modal-close {
        background: #1a2124;
        border: none;
        color: #fff;
        width: 32px;
        height: 32px;
        border-radius: 50%;
        font-size: 18px;
        line-height: 1;
        cursor: pointer;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        transition: background 120ms;
    }
    .uw-modal-close:hover { background: #243034; }

    /* Trim down the embedded PurchaseCredits component so it blends
       into the modal: hide its outer page padding and the big page
       heading (already provided by uw-modal-title). */
    .uw-modal .pc-modal-inner {
        background: transparent;
        padding: 0;
    }

    @media (max-width: 640px) {
        .uw-modal { padding: 16px 8px; }
        .uw-modal-dialog { padding: 18px 14px 16px; }
        .uw-balance { flex-direction: column; align-items: flex-start; gap: 14px; }
        .uw-buy-btn { width: 100%; justify-content: center; }
    }
</style>
@endpush

