                                            </div>
                                        </td>
                                        <td>
                                            <span class="uw-tx-amt {{ $isCredit ? 'is-in' : 'is-out' }}">
                                                {{ $isCredit ? '+' : '-' }}${{ number_format((float) $tx->amount, 2) }}
                                            </span>
                                        </td>
                                        <td>{{ $methodLabel }}</td>
                                        <td class="uw-tx-date">
                                            {{ \Carbon\Carbon::parse($tx->created_at)->format('M d, Y') }}
                                            <small>{{ \Carbon\Carbon::parse($tx->created_at)->format('h:i A') }}</small>
                                        </td>
                                        <td>
                                            <span class="uw-tx-status {{ $statusClass }}">
                                                @if($tx->status === 'completed')<i class="fa fa-check-circle"></i>@endif
                                                {{ ucfirst($tx->status ?: 'pending') }}
                                            </span>
                                        </td>
                                        <td class="uw-tx-ref">{{ $ref }}</td>
                                    </tr>
                                @empty
                                    <tr>
                                        <td colspan="6">
                                            <div class="uw-tx-empty">
                                                <i class="fa fa-receipt"></i>
                                                No transactions yet. Buy credits to get started.
                                            </div>
                                        </td>
                                    </tr>
                                @endforelse
                            </tbody>
                        </table>
                    </div>
                </div>
